//go:build amd64 && !purego

#include "textflag.h"

// func syndromeAVX2(out, vector, matrix *byte)
//
// H' is row-major. The left half of vector remains resident in Y8--Y12 and
// four rows are accumulated concurrently to expose instruction-level
// parallelism. The identity half is folded in a byte at a time after eight
// rows. No address depends on a secret bit.
TEXT ·syndromeAVX2(SB), NOSPLIT, $0-24
	MOVQ out+0(FP), DI
	MOVQ vector+8(FP), SI
	MOVQ matrix+16(FP), DX
	LEAQ 181(SI), R8

	VMOVDQU 0(SI), Y8
	VMOVDQU 32(SI), Y9
	VMOVDQU 64(SI), Y10
	VMOVDQU 96(SI), Y11
	VMOVDQU 128(SI), Y12
	MOVQ 160(SI), R14
	MOVQ 168(SI), R15
	MOVL 176(SI), R9
	MOVBLZX 180(SI), R10

	MOVQ $181, CX

byte_loop:
	XORQ R12, R12
	MOVQ $2, R11

four_row_loop:
	VPAND 0(DX), Y8, Y0
	VPAND 181(DX), Y8, Y1
	VPAND 362(DX), Y8, Y2
	VPAND 543(DX), Y8, Y3

	VPAND 32(DX), Y9, Y4
	VPAND 213(DX), Y9, Y5
	VPAND 394(DX), Y9, Y6
	VPAND 575(DX), Y9, Y7
	VPXOR Y4, Y0, Y0
	VPXOR Y5, Y1, Y1
	VPXOR Y6, Y2, Y2
	VPXOR Y7, Y3, Y3

	VPAND 64(DX), Y10, Y4
	VPAND 245(DX), Y10, Y5
	VPAND 426(DX), Y10, Y6
	VPAND 607(DX), Y10, Y7
	VPXOR Y4, Y0, Y0
	VPXOR Y5, Y1, Y1
	VPXOR Y6, Y2, Y2
	VPXOR Y7, Y3, Y3

	VPAND 96(DX), Y11, Y4
	VPAND 277(DX), Y11, Y5
	VPAND 458(DX), Y11, Y6
	VPAND 639(DX), Y11, Y7
	VPXOR Y4, Y0, Y0
	VPXOR Y5, Y1, Y1
	VPXOR Y6, Y2, Y2
	VPXOR Y7, Y3, Y3

	VPAND 128(DX), Y12, Y4
	VPAND 309(DX), Y12, Y5
	VPAND 490(DX), Y12, Y6
	VPAND 671(DX), Y12, Y7
	VPXOR Y4, Y0, Y0
	VPXOR Y5, Y1, Y1
	VPXOR Y6, Y2, Y2
	VPXOR Y7, Y3, Y3

	VEXTRACTI128 $1, Y0, X13
	VPXOR X13, X0, X0
	VPSHUFD $0x4e, X0, X13
	VPXOR X13, X0, X0
	VMOVQ X0, AX
	MOVQ 160(DX), BX
	ANDQ R14, BX
	XORQ BX, AX
	MOVQ 168(DX), BX
	ANDQ R15, BX
	XORQ BX, AX
	MOVL 176(DX), R13
	ANDL R9, R13
	XORQ R13, AX
	MOVBLZX 180(DX), R13
	ANDQ R10, R13
	XORQ R13, AX
	POPCNTQ AX, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	VEXTRACTI128 $1, Y1, X13
	VPXOR X13, X1, X1
	VPSHUFD $0x4e, X1, X13
	VPXOR X13, X1, X1
	VMOVQ X1, AX
	MOVQ 341(DX), BX
	ANDQ R14, BX
	XORQ BX, AX
	MOVQ 349(DX), BX
	ANDQ R15, BX
	XORQ BX, AX
	MOVL 357(DX), R13
	ANDL R9, R13
	XORQ R13, AX
	MOVBLZX 361(DX), R13
	ANDQ R10, R13
	XORQ R13, AX
	POPCNTQ AX, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	VEXTRACTI128 $1, Y2, X13
	VPXOR X13, X2, X2
	VPSHUFD $0x4e, X2, X13
	VPXOR X13, X2, X2
	VMOVQ X2, AX
	MOVQ 522(DX), BX
	ANDQ R14, BX
	XORQ BX, AX
	MOVQ 530(DX), BX
	ANDQ R15, BX
	XORQ BX, AX
	MOVL 538(DX), R13
	ANDL R9, R13
	XORQ R13, AX
	MOVBLZX 542(DX), R13
	ANDQ R10, R13
	XORQ R13, AX
	POPCNTQ AX, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	VEXTRACTI128 $1, Y3, X13
	VPXOR X13, X3, X3
	VPSHUFD $0x4e, X3, X13
	VPXOR X13, X3, X3
	VMOVQ X3, AX
	MOVQ 703(DX), BX
	ANDQ R14, BX
	XORQ BX, AX
	MOVQ 711(DX), BX
	ANDQ R15, BX
	XORQ BX, AX
	MOVL 719(DX), R13
	ANDL R9, R13
	XORQ R13, AX
	MOVBLZX 723(DX), R13
	ANDQ R10, R13
	XORQ R13, AX
	POPCNTQ AX, AX
	ANDQ $1, AX
	SHLQ $1, R12
	ORQ AX, R12

	ADDQ $724, DX
	DECQ R11
	JNZ four_row_loop

	MOVBLZX (R8), AX
	XORQ R12, AX
	MOVB AX, (DI)
	INCQ R8
	INCQ DI
	DECQ CX
	JNZ byte_loop

	VZEROUPPER
	RET
